def buscar(lista, valor):
    for i, x in enumerate(lista):
        if x == valor:
            return i
    return None

indice = buscar([10, 20, 30], 20)
print(indice)   # 1

indice = buscar([10, 20, 30], 99)
print(indice)   # None

def duplicar(x):
    if isinstance(x, (int, float)):
        return x * 2
    else:
        return "Solo acepto números"

print(duplicar(5))       # 10
print(duplicar(3.14))    # 6.28
print(duplicar("hola"))  # Solo acepto números
